/*
 * Blog admin: rich-text editor that publishes static blog pages to the
 * Codeberg `pages` repo via the Forgejo API (one commit per save).
 *
 * Files it owns: blog/posts.json, blog/<slug>/index.html, blog/index.html,
 * blog/feed.xml, sitemap-blog.xml, llms.txt, llms-full.txt, assets/blog/*.
 * Layout comes from _templates/* (generated by build.py).
 */
(function () {
  "use strict";
  var cfg = window.AGT_CONFIG || {};
  var API = (cfg.forgeApi || "https://codeberg.org/api/v1") + "/repos/" + (cfg.repo || "");
  var BRANCH = cfg.branch || "main";
  var TOKEN_KEY = "agt_forge_token";
  var IMG_MAX_W = 1600;

  var S = { posts: [], site: null, tpl: {}, editing: null, quill: null, cover: null, slugTouched: false };
  var $ = function (id) { return document.getElementById(id); };
  if (!$("tab-blog")) return;

  // ---------- small helpers ----------
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function xmlEsc(s) { return esc(s).replace(/&#39;/g, "&apos;"); }
  function store(k, v) { try { v === null ? sessionStorage.removeItem(k) : sessionStorage.setItem(k, v); } catch (e) {} }
  function load(k) { try { return sessionStorage.getItem(k); } catch (e) { return null; } }
  function say(text, isErr) { var m = $("blog-msg"); m.textContent = text || ""; m.className = "form-status " + (isErr ? "err" : "ok"); }
  function show(id) { ["blog-login", "blog-list", "blog-editor"].forEach(function (x) { $(x).classList.toggle("hidden", x !== id); }); }
  function today() { return new Date().toISOString().slice(0, 10); }
  function slugify(s) {
    return String(s).normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase()
      .replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80).replace(/-+$/, "");
  }
  function fill(tpl, map) {
    return tpl.replace(/\{\{([A-Z0-9_]+)\}\}/g, function (m, k) { return Object.prototype.hasOwnProperty.call(map, k) ? map[k] : m; });
  }
  function b64bytes(bytes) {
    var s = "";
    for (var i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    return btoa(s);
  }
  function b64text(str) { return b64bytes(new TextEncoder().encode(str)); }
  function humanDate(iso) {
    return new Date(iso + "T12:00:00Z").toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
  }
  function postUrl(p) { return S.site.url + "/blog/" + p.slug + "/"; }
  function absImg(p) { return p.image ? S.site.url + p.image : S.site.default_image; }
  function published() {
    return S.posts.filter(function (p) { return p.status === "published"; })
      .sort(function (a, b) { return a.date < b.date ? 1 : a.date > b.date ? -1 : 0; });
  }
  function textOf(html) {
    var doc = new DOMParser().parseFromString("<div>" + html + "</div>", "text/html");
    var root = doc.body.firstChild;
    root.querySelectorAll("h1,h2,h3,h4").forEach(function (h) { h.insertAdjacentText("beforebegin", "\n\n### "); h.insertAdjacentText("afterend", "\n"); });
    root.querySelectorAll("li").forEach(function (li) { li.insertAdjacentText("afterbegin", "\n- "); });
    root.querySelectorAll("p,br,blockquote,pre").forEach(function (el) { el.insertAdjacentText("beforebegin", "\n"); });
    return root.textContent.replace(/[ \t]+/g, " ").replace(/\n\s*\n\s*\n+/g, "\n\n").replace(/\n\s*\n(\s*- )/g, "\n$1")
      .split("\n").map(function (l) { return l.trim(); }).join("\n").trim();
  }
  function wordCount(html) { var t = textOf(html); return t ? t.split(/\s+/).length : 0; }
  function safeJson(obj) { return JSON.stringify(obj, null, 1).replace(/</g, "\\u003c"); }

  // ---------- Forgejo API ----------
  function headers(json) {
    var h = { Authorization: "token " + (load(TOKEN_KEY) || "") };
    if (json) h["Content-Type"] = "application/json";
    return h;
  }
  function api(path, opts) {
    opts = opts || {};
    return fetch(API + path, {
      method: opts.method || "GET", headers: headers(!!opts.body), cache: "no-store",
      body: opts.body ? JSON.stringify(opts.body) : undefined
    }).then(function (r) {
      if (r.status === 404 && opts.allow404) return null;
      if (!r.ok) return r.text().then(function (t) {
        var msg = t; try { msg = JSON.parse(t).message || t; } catch (e) {}
        throw new Error(r.status + " " + msg);
      });
      return r.status === 204 ? null : r.json();
    });
  }
  function encPath(p) { return p.split("/").map(encodeURIComponent).join("/"); }
  function raw(path) {
    return fetch(API + "/raw/" + encPath(path) + "?ref=" + encodeURIComponent(BRANCH), { headers: headers(false), cache: "no-store" })
      .then(function (r) { if (r.status === 404) return null; if (!r.ok) throw new Error("Cannot read " + path + " (" + r.status + ")"); return r.text(); });
  }
  function sha(path) {
    return api("/contents/" + encPath(path) + "?ref=" + encodeURIComponent(BRANCH), { allow404: true })
      .then(function (r) { return r && !Array.isArray(r) ? r.sha : null; });
  }
  // files: [{path, text}|{path, b64}|{path, del:true}]
  function commit(files, message) {
    return Promise.all(files.map(function (f) {
      return sha(f.path).then(function (s) {
        if (f.del) return s ? { operation: "delete", path: f.path, sha: s } : null;
        var content = f.b64 != null ? f.b64 : b64text(f.text);
        return s ? { operation: "update", path: f.path, content: content, sha: s } : { operation: "create", path: f.path, content: content };
      });
    })).then(function (ops) {
      ops = ops.filter(Boolean);
      if (!ops.length) return null;
      return api("/contents", { method: "POST", body: { branch: BRANCH, message: message, files: ops } });
    });
  }

  // ---------- connect ----------
  $("blog-login-form").addEventListener("submit", function (e) {
    e.preventDefault();
    store(TOKEN_KEY, $("forge-token").value.trim());
    $("forge-token").value = "";
    connect();
  });
  $("blog-logout").addEventListener("click", function () { store(TOKEN_KEY, null); show("blog-login"); say("Disconnected."); });

  function connect() {
    say("Connecting to Codeberg…");
    api("").then(function (repo) {
      if (!repo.permissions || !repo.permissions.push) throw new Error("This token cannot write to " + cfg.repo + ". Give it repository: Read and write.");
      return Promise.all([raw("_templates/site.json"), raw("_templates/post.html"), raw("_templates/blog-index.html"),
                          raw("_templates/llms.txt"), raw("_templates/llms-full.txt"), raw("blog/posts.json")]);
    }).then(function (r) {
      if (!r[0] || !r[1] || !r[2]) throw new Error("Templates missing in the repo. Run build.py and push first.");
      S.site = JSON.parse(r[0]);
      S.tpl = { post: r[1], index: r[2], llms: r[3], llmsFull: r[4] };
      S.posts = r[5] ? JSON.parse(r[5]) : [];
      renderList();
      show("blog-list");
      say("Connected. " + S.posts.length + " post(s).");
    }).catch(function (err) {
      if (/^401|^403/.test(err.message)) store(TOKEN_KEY, null);
      show("blog-login");
      say(err.message, true);
    });
  }

  // ---------- post list ----------
  function renderList() {
    var rows = S.posts.slice().sort(function (a, b) { return (b.updated || b.date) > (a.updated || a.date) ? 1 : -1; });
    $("posts-body").innerHTML = rows.length ? rows.map(function (p) {
      return "<tr><td><strong>" + esc(p.title) + "</strong><br><small>/blog/" + esc(p.slug) + "/</small></td>" +
        "<td><span class='badge" + (p.status === "draft" ? " draft" : "") + "'>" + esc(p.status) + "</span></td>" +
        "<td>" + esc(p.date) + "</td><td>" + esc(p.updated || "") + "</td>" +
        "<td><button class='btn btn-sm btn-navy' data-edit='" + esc(p.slug) + "'>Edit</button> " +
        (p.status === "published" ? "<a class='btn btn-sm btn-ghost' target='_blank' rel='noopener' href='/blog/" + esc(p.slug) + "/'>View ↗</a>" : "") +
        "</td></tr>";
    }).join("") : "<tr><td colspan='5'>No posts yet. Click “+ New post”.</td></tr>";
    document.querySelectorAll("[data-edit]").forEach(function (b) {
      b.addEventListener("click", function () { openEditor(S.posts.find(function (p) { return p.slug === b.dataset.edit; })); });
    });
  }
  $("post-new").addEventListener("click", function () { openEditor(null); });
  $("p-cancel").addEventListener("click", function () {
    if (dirty() && !confirm("Discard unsaved changes?")) return;
    show("blog-list");
  });

  // ---------- editor ----------
  function ensureQuill() {
    if (S.quill) return;
    if (!window.Quill) { say("Rich text editor failed to load (check your connection).", true); return; }
    S.quill = new window.Quill("#p-editor", {
      theme: "snow",
      placeholder: "Write your post… Use Heading 2/3 for sections.",
      modules: {
        toolbar: {
          container: [[{ header: [2, 3, 4, false] }], ["bold", "italic", "underline", "strike"],
                      [{ list: "ordered" }, { list: "bullet" }], ["blockquote", "code-block"],
                      ["link", "image", "video"], [{ align: [] }], ["clean"]],
          handlers: { image: pickInlineImage }
        }
      }
    });
    S.quill.on("text-change", seoCheck);
  }

  var snapshot = "";
  function formState() {
    return JSON.stringify([$("p-title").value, $("p-slug").value, $("p-desc").value, $("p-date").value, $("p-author").value,
                           $("p-tags").value, $("p-cover-alt").value, S.cover, S.quill ? S.quill.root.innerHTML : ""]);
  }
  function dirty() { return !$("blog-editor").classList.contains("hidden") && formState() !== snapshot; }
  window.addEventListener("beforeunload", function (e) { if (dirty()) { e.preventDefault(); e.returnValue = ""; } });

  function openEditor(post) {
    ensureQuill();
    S.editing = post || null;
    S.cover = post && post.image ? { src: post.image, existing: true } : null;
    S.slugTouched = !!post;
    $("p-title").value = post ? post.title : "";
    $("p-slug").value = post ? post.slug : "";
    $("p-slug").disabled = !!(post && post.everPublished);
    $("p-desc").value = post ? post.description : "";
    $("p-date").value = post ? post.date : today();
    $("p-author").value = post ? post.author : S.site.default_author;
    $("p-tags").value = post ? (post.tags || []).join(", ") : "";
    $("p-cover-alt").value = post ? post.imageAlt || "" : "";
    $("p-cover").value = "";
    $("p-delete").classList.toggle("hidden", !post);
    $("p-publish").textContent = post && post.status === "published" ? "Update post" : "Publish";
    $("p-draft").textContent = post && post.status === "published" ? "Unpublish (draft)" : "Save as draft";
    if (S.quill) {
      S.quill.setContents([]);
      if (post) S.quill.clipboard.dangerouslyPasteHTML(post.content || "");
      S.quill.history.clear();
    }
    renderCover();
    updateUrl();
    seoCheck();
    show("blog-editor");
    say(post ? "Editing “" + post.title + "”." : "New post.");
    snapshot = formState();
    window.scrollTo(0, 0);
  }

  $("p-title").addEventListener("input", function () { if (!S.slugTouched && !$("p-slug").disabled) $("p-slug").value = slugify($("p-title").value); updateUrl(); seoCheck(); });
  $("p-slug").addEventListener("input", function () { S.slugTouched = true; $("p-slug").value = slugify($("p-slug").value); updateUrl(); });
  $("p-desc").addEventListener("input", seoCheck);
  $("p-cover-alt").addEventListener("input", seoCheck);
  function updateUrl() {
    $("p-url").textContent = S.site ? S.site.url + "/blog/" + ($("p-slug").value || "…") + "/" + ($("p-slug").disabled ? "  (URL is locked after publishing so links don't break)" : "") : "";
  }

  // Resize an image file to a data URL (JPEG unless PNG/GIF/WebP transparency matters).
  function readImage(file) {
    return new Promise(function (resolve, reject) {
      if (!/^image\//.test(file.type)) return reject(new Error("Not an image"));
      var url = URL.createObjectURL(file);
      var img = new Image();
      img.onload = function () {
        var scale = Math.min(1, IMG_MAX_W / img.naturalWidth);
        var c = document.createElement("canvas");
        c.width = Math.round(img.naturalWidth * scale);
        c.height = Math.round(img.naturalHeight * scale);
        var ctx = c.getContext("2d");
        var png = file.type === "image/png" || file.type === "image/gif" || file.type === "image/webp";
        if (!png) { ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, c.width, c.height); }
        ctx.drawImage(img, 0, 0, c.width, c.height);
        URL.revokeObjectURL(url);
        resolve(c.toDataURL(png ? "image/png" : "image/jpeg", 0.85));
      };
      img.onerror = function () { URL.revokeObjectURL(url); reject(new Error("Could not read image")); };
      img.src = url;
    });
  }
  function pickInlineImage() {
    var input = document.createElement("input");
    input.type = "file"; input.accept = "image/*";
    input.onchange = function () {
      if (!input.files[0]) return;
      readImage(input.files[0]).then(function (data) {
        var range = S.quill.getSelection(true);
        S.quill.insertEmbed(range.index, "image", data, "user");
        S.quill.setSelection(range.index + 1);
      }).catch(function (e) { say(e.message, true); });
    };
    input.click();
  }
  $("p-cover").addEventListener("change", function () {
    var f = $("p-cover").files[0];
    if (!f) return;
    readImage(f).then(function (data) { S.cover = { src: data, existing: false }; renderCover(); seoCheck(); })
      .catch(function (e) { say(e.message, true); });
  });
  $("p-cover-remove").addEventListener("click", function () { S.cover = null; $("p-cover").value = ""; renderCover(); seoCheck(); });
  function renderCover() {
    var img = $("p-cover-preview");
    img.classList.toggle("hidden", !S.cover);
    $("p-cover-remove").classList.toggle("hidden", !S.cover);
    if (S.cover) img.src = S.cover.src;
  }

  function seoCheck() {
    var t = $("p-title").value.trim(), d = $("p-desc").value.trim();
    var html = S.quill ? S.quill.getSemanticHTML() : "";
    var words = wordCount(html);
    var h2 = (html.match(/<h2/g) || []).length;
    var links = (html.match(/<a /g) || []).length;
    $("p-desc-count").textContent = "(" + d.length + "/160)";
    var checks = [
      [t.length >= 20 && t.length <= 65, "Title 20–65 characters (" + t.length + ")"],
      [d.length >= 120 && d.length <= 160, "Meta description 120–160 characters (" + d.length + ")"],
      [words >= 600, "At least 600 words (" + words + ")"],
      [h2 >= 2, "Two or more H2 section headings (" + h2 + ")"],
      [links >= 1, "At least one link, e.g. to /group-flights/ or /contact/ (" + links + ")"],
      [!!S.cover, "Featured image added"],
      [!S.cover || $("p-cover-alt").value.trim().length > 3, "Featured image has alt text"]
    ];
    $("seo-check").innerHTML = "<strong>SEO checklist</strong><ul>" + checks.map(function (c) {
      return "<li class='" + (c[0] ? "ok" : "todo") + "'>" + (c[0] ? "✓ " : "○ ") + esc(c[1]) + "</li>";
    }).join("") + "</ul><p class='note'>Recommendations only; you can publish anyway.</p>";
  }

  // ---------- save / publish ----------
  $("p-publish").addEventListener("click", function () { save("published"); });
  $("p-draft").addEventListener("click", function () { save("draft"); });
  $("p-delete").addEventListener("click", function () {
    var p = S.editing;
    if (!p || !confirm("Permanently delete “" + p.title + "”? Its page will go offline.")) return;
    S.posts = S.posts.filter(function (x) { return x !== p; });
    var files = [{ path: "blog/" + p.slug + "/index.html", del: true }].concat(sharedFiles());
    busy(true);
    say("Deleting…");
    commit(files, "Delete blog post: " + p.title).then(function () {
      say("Deleted “" + p.title + "”. The live site updates in a minute or two.");
      snapshot = formState(); renderList(); show("blog-list");
    }).catch(fail).finally(function () { busy(false); });
  });

  function busy(on) { ["p-publish", "p-draft", "p-delete", "blog-rebuild"].forEach(function (id) { $(id).disabled = on; }); }
  function fail(err) {
    say("Save failed: " + err.message + (/409|sha/i.test(err.message) ? " (the repo changed; reconnect and try again)" : ""), true);
    // reload posts from the repo so local state matches what is committed
    raw("blog/posts.json").then(function (t) { S.posts = t ? JSON.parse(t) : []; renderList(); }).catch(function () {});
  }

  function save(status) {
    if (!S.quill) return;
    var title = $("p-title").value.trim();
    var slug = slugify($("p-slug").value || title);
    var desc = $("p-desc").value.trim();
    var old = S.editing;
    if (!title) return say("Please add a title.", true);
    if (!slug) return say("Please add a URL slug.", true);
    if (!desc) return say("Please add a meta description.", true);
    if (S.posts.some(function (p) { return p.slug === slug && p !== old; })) return say("Another post already uses /blog/" + slug + "/.", true);
    if (S.quill.getLength() < 2) return say("The post is empty.", true);

    var files = [];
    var stamp = Date.now().toString(36);
    // Content: move pasted/inserted data: images into assets/blog/ files
    var doc = new DOMParser().parseFromString("<div>" + S.quill.getSemanticHTML().replace(/&nbsp;/g, " ") + "</div>", "text/html");
    var root = doc.body.firstChild;
    root.querySelectorAll("img").forEach(function (img, i) {
      var src = img.getAttribute("src") || "";
      var m = src.match(/^data:image\/(png|jpeg|jpg|gif|webp);base64,(.+)$/);
      if (m) {
        var path = "assets/blog/" + slug + "-" + stamp + "-" + (i + 1) + "." + (m[1] === "jpeg" ? "jpg" : m[1]);
        files.push({ path: path, b64: m[2] });
        img.setAttribute("src", "/" + path);
      }
      if (!img.getAttribute("alt")) img.setAttribute("alt", title);
      img.setAttribute("loading", "lazy");
      img.setAttribute("decoding", "async");
    });
    root.querySelectorAll("a[href]").forEach(function (a) {
      var href = a.getAttribute("href");
      if (/^https?:\/\//.test(href) && href.indexOf(S.site.url) !== 0) a.setAttribute("rel", "noopener");
      else a.removeAttribute("target");
    });
    var content = root.innerHTML;

    var image = "";
    if (S.cover) {
      if (S.cover.existing) image = S.cover.src;
      else {
        var cm = S.cover.src.match(/^data:image\/(png|jpeg);base64,(.+)$/);
        var cpath = "assets/blog/" + slug + "-cover-" + stamp + "." + (cm[1] === "jpeg" ? "jpg" : "png");
        files.push({ path: cpath, b64: cm[2] });
        image = "/" + cpath;
      }
    }

    var post = {
      slug: slug, title: title, description: desc, content: content,
      image: image, imageAlt: $("p-cover-alt").value.trim(),
      tags: $("p-tags").value.split(",").map(function (t) { return t.trim(); }).filter(Boolean),
      author: $("p-author").value.trim() || S.site.default_author,
      date: $("p-date").value || today(), updated: today(), status: status,
      everPublished: !!(old && old.everPublished) || status === "published"
    };

    var idx = S.posts.indexOf(old);
    if (idx >= 0) S.posts[idx] = post; else S.posts.push(post);

    if (old && old.slug !== slug) files.push({ path: "blog/" + old.slug + "/index.html", del: true });
    if (status === "published") files.push({ path: "blog/" + slug + "/index.html", text: renderPost(post) });
    else files.push({ path: "blog/" + slug + "/index.html", del: true });
    files = files.concat(sharedFiles());

    busy(true);
    say(status === "published" ? "Publishing…" : "Saving draft…");
    var verb = status === "published" ? (old && old.status === "published" ? "Update" : "Publish") : "Save draft";
    commit(files, verb + " blog post: " + title).then(function () {
      S.editing = post;
      $("p-slug").disabled = post.everPublished;
      $("p-delete").classList.remove("hidden");
      $("p-publish").textContent = status === "published" ? "Update post" : "Publish";
      $("p-draft").textContent = status === "published" ? "Unpublish (draft)" : "Save as draft";
      S.cover = post.image ? { src: post.image, existing: true } : null;
      snapshot = formState();
      renderList();
      say(status === "published"
        ? "Published! Live in a minute or two at " + postUrl(post)
        : "Draft saved (not visible on the site).");
    }).catch(function (e) {
      // roll back local change
      if (idx >= 0) S.posts[idx] = old; else S.posts.splice(S.posts.indexOf(post), 1);
      fail(e);
    }).finally(function () { busy(false); });
  }

  $("blog-rebuild").addEventListener("click", function () {
    if (!confirm("Re-render every published post and blog file with the current templates?")) return;
    var files = published().map(function (p) { return { path: "blog/" + p.slug + "/index.html", text: renderPost(p) }; })
      .concat(sharedFiles());
    busy(true);
    say("Rebuilding " + files.length + " files…");
    commit(files, "Rebuild blog pages").then(function () { say("Rebuilt. The live site updates in a minute or two."); })
      .catch(fail).finally(function () { busy(false); });
  });

  // ---------- rendering ----------
  function sharedFiles() {
    var list = published();
    return [
      { path: "blog/posts.json", text: JSON.stringify(S.posts, null, 1) + "\n" },
      { path: "blog/index.html", text: renderIndex(list) },
      { path: "blog/feed.xml", text: renderFeed(list) },
      { path: "sitemap-blog.xml", text: renderSitemap(list) },
      { path: "llms.txt", text: fill(S.tpl.llms, { BLOG_LIST: blogList(list) }) },
      { path: "llms-full.txt", text: fill(S.tpl.llmsFull, { BLOG_FULL: blogFull(list) }) }
    ];
  }

  // Must match blog_llms_list()/blog_llms_full() in build.py
  function blogList(list) {
    if (!list.length) return "- No posts published yet.";
    return list.map(function (p) { return "- [" + p.title + "](" + postUrl(p) + "): " + p.description; }).join("\n");
  }
  function blogFull(list) {
    return list.map(function (p) {
      return "\n---\n\n## " + p.title + "\n\nURL: " + postUrl(p) + "\nPublished: " + p.date + "\n\n" + textOf(p.content) + "\n";
    }).join("");
  }

  function card(p, level) {
    var h = level || "h2";
    var mins = Math.max(1, Math.round(wordCount(p.content) / 220));
    return "<article class='card post-card'>" +
      "<a class='post-card-img' href='/blog/" + esc(p.slug) + "/' tabindex='-1' aria-hidden='true'>" +
      (p.image ? "<img src='" + esc(p.image) + "' alt='' loading='lazy' decoding='async'>" : "<span class='post-card-ph'>✈️</span>") + "</a>" +
      "<div class='post-card-body'><p class='post-meta'><time datetime='" + esc(p.date) + "'>" + esc(humanDate(p.date)) + "</time> · " + mins + " min read</p>" +
      "<" + h + "><a href='/blog/" + esc(p.slug) + "/'>" + esc(p.title) + "</a></" + h + ">" +
      "<p>" + esc(p.description) + "</p><a class='read-more' href='/blog/" + esc(p.slug) + "/'>Read more<span class='sr-only'> about " + esc(p.title) + "</span> →</a></div></article>";
  }

  function renderPost(p) {
    var url = postUrl(p);
    var words = wordCount(p.content);
    var org = { "@id": S.site.org_id };
    var author = p.author === S.site.name || p.author === S.site.default_author
      ? { "@type": "Organization", "name": p.author, "url": S.site.url + "/" } : { "@type": "Person", "name": p.author };
    var graph = {
      "@context": "https://schema.org",
      "@graph": [
        S.site.org,
        { "@type": "BlogPosting", "@id": url + "#article", "headline": p.title.slice(0, 110), "description": p.description,
          "image": [absImg(p)], "datePublished": p.date, "dateModified": p.updated || p.date, "author": author,
          "publisher": org, "mainEntityOfPage": { "@id": url + "#webpage" }, "isPartOf": { "@id": S.site.url + "/blog/#blog" },
          "keywords": (p.tags || []).join(", "), "wordCount": words, "inLanguage": "en-US",
          "articleSection": (p.tags && p.tags[0]) || "Group Travel" },
        { "@type": "WebPage", "@id": url + "#webpage", "url": url, "name": p.title, "description": p.description,
          "isPartOf": { "@id": S.site.website_id }, "breadcrumb": { "@id": url + "#breadcrumb" }, "inLanguage": "en-US",
          "primaryImageOfPage": { "@type": "ImageObject", "url": absImg(p) } },
        { "@type": "BreadcrumbList", "@id": url + "#breadcrumb", "itemListElement": [
          { "@type": "ListItem", "position": 1, "name": "Home", "item": S.site.url + "/" },
          { "@type": "ListItem", "position": 2, "name": "Blog", "item": S.site.url + "/blog/" },
          { "@type": "ListItem", "position": 3, "name": p.title, "item": url }] }
      ]
    };
    var related = published().filter(function (x) { return x.slug !== p.slug; }).slice(0, 3);
    var tags = p.tags || [];
    return fill(S.tpl.post, {
      SLUG: esc(p.slug),
      TITLE: esc(p.title + " | " + S.site.name),
      H1: esc(p.title),
      DESC: esc(p.description),
      IMAGE: esc(absImg(p)),
      IMAGE_ALT: esc(p.imageAlt || p.title),
      AUTHOR: esc(p.author),
      PUBLISHED_ISO: esc(p.date),
      MODIFIED_ISO: esc(p.updated || p.date),
      DATE_HUMAN: esc(humanDate(p.date)),
      UPDATED_HTML: p.updated && p.updated !== p.date ? " · Updated <time datetime='" + esc(p.updated) + "'>" + esc(humanDate(p.updated)) + "</time>" : "",
      READ_MIN: String(Math.max(1, Math.round(words / 220))),
      KICKER: tags.length ? esc(tags[0]) : "Group Travel",
      ARTICLE_TAGS: tags.map(function (t) { return '\n<meta property="article:tag" content="' + esc(t) + '">'; }).join(""),
      COVER: p.image ? "<figure class='post-cover'><img src='" + esc(p.image) + "' alt='" + esc(p.imageAlt || p.title) + "' fetchpriority='high' decoding='async'></figure>" : "",
      CONTENT: p.content,
      TAGS_HTML: tags.length ? "<ul class='tag-list' aria-label='Tags'>" + tags.map(function (t) { return "<li>" + esc(t) + "</li>"; }).join("") + "</ul>" : "",
      RELATED: related.length ? "<section class='block alt'><div class='wrap'><h2>More from the blog</h2><div class='grid post-grid'>" +
        related.map(function (r) { return card(r, "h3"); }).join("") + "</div></div></section>" : "",
      JSONLD: safeJson(graph)
    });
  }

  function renderIndex(list) {
    var blogLd = {
      "@context": "https://schema.org", "@type": "Blog", "@id": S.site.url + "/blog/#blog", "url": S.site.url + "/blog/",
      "name": S.site.blog_title, "description": S.site.blog_desc, "publisher": { "@id": S.site.org_id }, "inLanguage": "en-US",
      "blogPost": list.map(function (p) {
        return { "@type": "BlogPosting", "@id": postUrl(p) + "#article", "headline": p.title.slice(0, 110), "url": postUrl(p),
                 "datePublished": p.date, "dateModified": p.updated || p.date, "image": absImg(p) };
      })
    };
    return fill(S.tpl.index, {
      POST_LIST: list.length ? list.map(function (p) { return card(p, "h2"); }).join("") : "<p class='empty'>No posts yet. Check back soon!</p>",
      BLOG_JSONLD: safeJson(blogLd)
    });
  }

  function renderFeed(list) {
    var abs = function (html) { return html.replace(/(src|href)="\//g, '$1="' + S.site.url + "/"); };
    var items = list.slice(0, 30).map(function (p) {
      return "  <item>\n    <title>" + xmlEsc(p.title) + "</title>\n    <link>" + postUrl(p) + "</link>\n" +
        "    <guid isPermaLink=\"true\">" + postUrl(p) + "</guid>\n    <pubDate>" + new Date(p.date + "T12:00:00Z").toUTCString() + "</pubDate>\n" +
        (p.tags || []).map(function (t) { return "    <category>" + xmlEsc(t) + "</category>\n"; }).join("") +
        "    <description>" + xmlEsc(p.description) + "</description>\n" +
        "    <content:encoded><![CDATA[" + (p.image ? "<p><img src=\"" + absImg(p) + "\" alt=\"\"></p>" : "") +
        abs(p.content).replace(/]]>/g, "]]]]><![CDATA[>") + "]]></content:encoded>\n  </item>\n";
    }).join("");
    return '<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:content="http://purl.org/rss/1.0/modules/content/">\n<channel>\n' +
      "  <title>" + xmlEsc(S.site.name + " Blog") + "</title>\n  <link>" + S.site.url + "/blog/</link>\n" +
      "  <description>" + xmlEsc(S.site.blog_desc) + "</description>\n  <language>en-us</language>\n" +
      '  <atom:link href="' + S.site.url + '/blog/feed.xml" rel="self" type="application/rss+xml"/>\n' +
      "  <lastBuildDate>" + new Date().toUTCString() + "</lastBuildDate>\n" +
      "  <image><url>" + S.site.logo + "</url><title>" + xmlEsc(S.site.name + " Blog") + "</title><link>" + S.site.url + "/blog/</link></image>\n" +
      items + "</channel>\n</rss>\n";
  }

  function renderSitemap(list) {
    var latest = list.reduce(function (m, p) { var d = p.updated || p.date; return d > m ? d : m; }, today());
    var urls = "  <url><loc>" + S.site.url + "/blog/</loc><lastmod>" + latest + "</lastmod><changefreq>weekly</changefreq><priority>0.8</priority></url>\n" +
      list.map(function (p) {
        return "  <url>\n    <loc>" + postUrl(p) + "</loc>\n    <lastmod>" + (p.updated || p.date) + "</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.7</priority>\n" +
          (p.image ? "    <image:image><image:loc>" + xmlEsc(absImg(p)) + "</image:loc></image:image>\n" : "") + "  </url>\n";
      }).join("");
    return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">\n' + urls + "</urlset>\n";
  }

  // auto-connect if a token is already in this tab
  if (load(TOKEN_KEY)) connect(); else show("blog-login");
})();
